   "url_medio": "https://saludconlupa.com/opinion/cien-dias-de-deriva-la-salud-entre-la-improvisacion-y-el-continuismo/",
   "sintesis": "El gobierno de Fujimori diluye las reformas prometidas y muestra dificultades para conducir un sector golpeado por epidemias y amenazado por El Niño. L a pandemia dejó al descubierto la precariedad del sistema de salud peruano: servicios fragmentados, financiamiento segmentado y una descentralización que transfirió responsabilidades sin asegurar capacidades.",
   "puntos": [
    "El gobierno de Fujimori diluye las reformas prometidas y muestra dificultades para conducir un sector golpeado por epidemias y amenazado por El Niño.",
    "L a pandemia dejó al descubierto la precariedad del sistema de salud peruano: servicios fragmentados, financiamiento segmentado y una descentralización que transfirió responsabilidades sin asegurar capacidades.",
    "La corrupción y el deterioro de la gestión agravaron esas fallas."
   ],
   "acceso": "abierto"
